"use strict";

/**
 * A generated standard is edited through its source parts, never through
 * the generated output itself.
 *
 * `tools/build-standard.js` assembles the split files in `docs/standards/`
 * into whole, human-readable documents and stamps an unmistakable marker
 * into the head of every one it writes: a line containing "Generated file —
 * do not edit directly." together with "Produced by
 * `tools/build-standard.js`". This rule reads the write's TARGET file — its
 * existing content already on disk, through `ctx.readFile`, never the new
 * content about to replace it — and asks before a write lands on a file
 * that already carries that marker.
 *
 * Detection is content-based on purpose: no filename is hard-coded here.
 * `tools/build-standard.js`'s own `DOCUMENTS` list is free to grow, and this
 * rule keeps working against whatever it produces without a second place to
 * update — a hard-coded filename list would drift the moment a new
 * generated document was added.
 */

const { ask, pass } = require("../lib/decision");

/** Tool names this rule inspects: file-write calls on both hosts. */
const WRITE_TOOLS = /^(Write|Edit|MultiEdit|NotebookEdit|apply_patch|write_file)$/;

/**
 * The marker `tools/build-standard.js` writes into the head of every
 * document it generates, matched within a single line so an unrelated file
 * that merely mentions the two phrases far apart from each other does not
 * qualify.
 */
const GENERATED_MARKER = /Generated file — do not edit directly\.[^\n]*Produced by `tools\/build-standard\.js`/;

module.exports = {
  /** kebab-case, unique, equals the filename without .js */
  id: "no-edit-generated-docs",

  /** one line, shown by `softela-ai doctor` */
  title: "A generated standard is edited through its source parts, not the output",

  /** which host events this rule can fire on */
  events: ["PreToolUse"],

  /** which tool names it applies to; null means every tool */
  tools: WRITE_TOOLS,

  /** the strongest action this rule may ever return */
  defaultAction: "ask",

  /** which catalogue group this rule belongs to — see RULES.md */
  group: "agent",

  /** needs no project configuration: the marker already on disk decides */
  requiresConfig: [],

  /** optional: only active when this module is enabled */
  requiresModule: null,

  /**
   * @param {object} ctx The evaluation context.
   * @returns {null | {action: "ask", reason: string, fix: string}} `ask`
   * when the file already on disk at `ctx.filePath` carries the generated-
   * file marker; `pass` when there is no path, the file does not exist yet,
   * it cannot be read, or its current content carries no marker.
   */
  evaluate(ctx) {
    const filePath = ctx.filePath || "";
    if (!filePath) return pass();

    const onDisk = ctx.readFile(filePath);
    if (onDisk === null) return pass();
    if (!GENERATED_MARKER.test(onDisk)) return pass();

    return ask(
      "This file is generated by tools/build-standard.js from parts in docs/standards/ — a direct edit here is overwritten the next time the script runs, and never reaches the part anyone else actually reads.",
      'Edit the corresponding part in docs/standards/ and run "node tools/build-standard.js" to regenerate this file instead.',
    );
  },
};
